fn run_exists(shard: &mut Shard, run: RunId) -> bool {
    assert_eq!(
        shard.enqueue(ShardCommand::Inspect {
            run,
            correlation: 999
        }),
        Ok(())
    );
    assert_eq!(shard.tick(), Ok(true));
    matches!(
        shard.take_inspect_response(),
        Some(vb_runtime::shard::InspectResponse::Found(_))
    )
}

